<?php get_header(); ?><main id="content" class="site-content rp-container"><header class="page-heading"><h1><?php the_archive_title(); ?></h1><?php the_archive_description('<div class="entry-excerpt">','</div>'); ?></header><div class="single-layout<?php echo get_theme_mod('rss_prism_show_sidebar',true)&&is_active_sidebar('sidebar-1')?'':' single-layout--no-sidebar'; ?>"><div><?php if(have_posts()):?><div class="entry-grid"><?php while(have_posts()):the_post();rss_prism_post_card();endwhile;?></div><?php the_posts_pagination(); ?><?php else:?><div class="entry-card entry-card--plain"><?php esc_html_e('No content was found in this archive.','rss-prism'); ?></div><?php endif;?></div><?php rss_prism_sidebar();?></div></main><?php get_footer(); ?>